using System.Text.Json;
using Clary.Api.Identity;
using NpgsqlTypes;
namespace Clary.Api;
public record TicketReportRow(string Id,Dictionary<string,string> Values,Guid? TicketId=null);
public record TicketReportPage(IReadOnlyList<TicketReportRow> Items,string? NextCursor,int Total);
public sealed partial class TicketRepository {
 record ReportCursor(Guid Company,string Subject,string Id);
 public async Task<TicketReportPage> ReportAsync(CompanyContext c,string subject,TicketQuery filter,CancellationToken ct){
  if(subject is not ("Tickets" or "User workload" or "Asset repairs"))throw new ArgumentException("Choose a valid ticket report.");if(filter.Limit is <1 or >100)throw new ArgumentException("Limit must be 1 to 100.");ReportCursor? after=null;if(filter.Cursor is not null){try{after=JsonSerializer.Deserialize<ReportCursor>(Convert.FromBase64String(filter.Cursor),Json);}catch(Exception ex)when(ex is FormatException or JsonException){throw new ArgumentException("Invalid cursor.");}if(after?.Company!=c.CompanyId||after.Subject!=subject)throw new ArgumentException("Invalid cursor.");}
  await using var conn=await db.OpenConnectionAsync(ct);await using var tx=await conn.BeginTransactionAsync(ct);c=await TicketAccess.LiveAsync(conn,tx,c,ct);
  var matched="SELECT t.* FROM equipment_tickets t WHERE t.company_id=@company AND NOT t.dismissed AND "+Visible+" AND (@search='' OR strpos(lower(t.title),lower(@search))>0) AND (@status IS NULL OR CASE t.state WHEN 'Ready' THEN 'Assigned' WHEN 'Completed' THEN 'Complete' WHEN 'Cancelled' THEN 'Canceled' ELSE t.state END=@status) AND (@type IS NULL OR t.type=@type) AND (@recipient IS NULL OR t.recipient_employee_id=@recipient) AND (@location IS NULL OR t.location_id=@location) AND (@asset IS NULL OR EXISTS(SELECT 1 FROM ticket_asset_links x WHERE x.company_id=t.company_id AND x.ticket_id=t.id AND x.asset_id=@asset)) AND (@assignee IS NULL OR t.assignment_mode='All' OR EXISTS(SELECT 1 FROM ticket_assignees x WHERE x.company_id=t.company_id AND x.ticket_id=t.id AND x.user_id=@assignee)) AND (NOT @overdue OR t.due_date<@today AND t.state NOT IN ('Complete','Canceled','Completed','Cancelled'))";
  var sql=subject switch{
   "Tickets"=>"""
   SELECT t.id::text AS key,t.id AS ticket,jsonb_build_object('Ticket',t.title,'Type',t.type,'Status',CASE t.state WHEN 'Ready' THEN 'Assigned' WHEN 'Completed' THEN 'Complete' WHEN 'Cancelled' THEN 'Canceled' ELSE t.state END,'Due date',coalesce(t.due_date::text,'—'),'Assigned to',CASE WHEN t.assignment_mode='All' THEN 'Everyone' ELSE coalesce((SELECT string_agg(u.display_name,', ' ORDER BY u.display_name) FROM ticket_assignees x JOIN users u ON u.id=x.user_id WHERE x.company_id=t.company_id AND x.ticket_id=t.id),'—') END,'Person',coalesce(e.display_name,'—'),'Location',coalesce(l.name,'—'),'Created by',coalesce(t.creator_name,'—'),'Approved by',coalesce(t.approver_name,'—'),'Approved date',coalesce(t.approved_at::date::text,'—')) AS vals FROM matched t LEFT JOIN employees e ON e.company_id=t.company_id AND e.id=t.recipient_employee_id LEFT JOIN locations l ON l.company_id=t.company_id AND l.id=t.location_id
   """,
   "User workload"=>"""
   SELECT u.id::text AS key,NULL::uuid AS ticket,jsonb_build_object('User',u.display_name,'Total tickets',count(t.id)::text,'Open tickets',count(t.id) FILTER(WHERE t.state NOT IN ('Complete','Canceled','Completed','Cancelled'))::text,'In progress',count(t.id) FILTER(WHERE t.state='In Progress')::text,'Overdue',count(t.id) FILTER(WHERE t.due_date<@today AND t.state NOT IN ('Complete','Canceled','Completed','Cancelled'))::text) AS vals FROM memberships m JOIN users u ON u.id=m.user_id LEFT JOIN ticket_assignees x ON x.company_id=m.company_id AND x.user_id=u.id LEFT JOIN matched t ON t.company_id=x.company_id AND t.id=x.ticket_id AND t.assignment_mode='Users' WHERE m.company_id=@company AND m.active AND u.active AND (@manager OR u.id=@user) GROUP BY u.id,u.display_name
   UNION ALL SELECT 'shared',NULL::uuid,jsonb_build_object('User','Everyone (shared)','Total tickets',count(*)::text,'Open tickets',count(*) FILTER(WHERE state NOT IN ('Complete','Canceled','Completed','Cancelled'))::text,'In progress',count(*) FILTER(WHERE state='In Progress')::text,'Overdue',count(*) FILTER(WHERE due_date<@today AND state NOT IN ('Complete','Canceled','Completed','Cancelled'))::text) FROM matched WHERE assignment_mode='All' HAVING count(*)>0
   """,
   _=>"""
   SELECT a.id::text AS key,NULL::uuid AS ticket,jsonb_build_object('Asset tag',a.asset_tag,'Equipment name',a.computer,'Repair tickets',count(t.id)::text,'Open repairs',count(t.id) FILTER(WHERE t.state NOT IN ('Complete','Canceled','Completed','Cancelled'))::text,'Last completed',coalesce(max(t.updated_at) FILTER(WHERE t.state IN ('Complete','Completed'))::date::text,'—'),'Tickets',string_agg(t.title,'; ' ORDER BY t.created_at DESC)) AS vals FROM matched t JOIN ticket_asset_links x ON x.company_id=t.company_id AND x.ticket_id=t.id JOIN inventory_assets a ON a.company_id=x.company_id AND a.id=x.asset_id WHERE t.type='Repair' AND x.outcome='Repair' AND (@inventory OR a.employee_id=@employee) GROUP BY a.id,a.asset_tag,a.computer
   """
  };
  await using var q=Q(conn,tx,c,"WITH matched AS ("+matched+"), rows AS ("+sql+"), counted AS (SELECT count(*)::integer AS total FROM rows) SELECT r.key,r.ticket,r.vals::text,c.total FROM counted c LEFT JOIN LATERAL (SELECT * FROM rows WHERE (@after IS NULL OR key>@after) ORDER BY key LIMIT @limit) r ON true");q.Parameters.AddWithValue("manager",TicketAccess.Manager(c));q.Parameters.AddWithValue("inventory",AccountPermissions.Allows(c,CompanyCapability.Read));P(q,"employee",c.EmployeeId,NpgsqlDbType.Uuid);q.Parameters.AddWithValue("search",Text(filter.Search,200));P(q,"status",string.IsNullOrWhiteSpace(filter.Status)?null:filter.Status,NpgsqlDbType.Text);P(q,"type",string.IsNullOrWhiteSpace(filter.Type)?null:filter.Type,NpgsqlDbType.Text);P(q,"recipient",filter.RecipientId,NpgsqlDbType.Uuid);P(q,"location",filter.LocationId,NpgsqlDbType.Uuid);P(q,"asset",filter.AssetId,NpgsqlDbType.Uuid);P(q,"assignee",filter.AssigneeId,NpgsqlDbType.Uuid);q.Parameters.AddWithValue("overdue",filter.Overdue);q.Parameters.AddWithValue("today",filter.Today??DateOnly.FromDateTime(DateTime.UtcNow));P(q,"after",after?.Id,NpgsqlDbType.Text);q.Parameters.AddWithValue("limit",filter.Limit+1);
  var rows=new List<TicketReportRow>();var total=0;await using(var r=await q.ExecuteReaderAsync(ct))while(await r.ReadAsync(ct)){total=r.GetInt32(3);if(!r.IsDBNull(0))rows.Add(new(r.GetString(0),JsonSerializer.Deserialize<Dictionary<string,string>>(r.GetString(2),Json)!,r.IsDBNull(1)?null:r.GetGuid(1)));}var more=rows.Count>filter.Limit;if(more)rows.RemoveAt(rows.Count-1);return new(rows,more?Convert.ToBase64String(JsonSerializer.SerializeToUtf8Bytes(new ReportCursor(c.CompanyId,subject,rows[^1].Id),Json)):null,total);
 }
}
